/* Local progressive-enhancement subset for this starter: hx-get, hx-target, hx-push-url,
   hx-trigger input/change, and hx-* links. Replace with official HTMX for advanced features. */
(()=>{const qs=(e,s)=>e.querySelector(s),target=(e)=>document.querySelector(e.getAttribute('hx-target')||'body');async function request(e){let url=e.getAttribute('hx-get');if(!url)return;const form=e.tagName==='FORM'?e:e.closest('form'),data=form?new FormData(form):null;if(data){const p=new URLSearchParams(data);url+=(url.includes('?')?'&':'?')+p.toString()}const r=await fetch(url,{headers:{'HX-Request':'true'}});if(!r.ok)return;const t=target(e);if(t)t.innerHTML=await r.text();if(e.getAttribute('hx-push-url')==='true')history.pushState({},'',url)}document.addEventListener('click',e=>{const a=e.target.closest('[hx-get]');if(a&&a.tagName==='A'){e.preventDefault();request(a)}});document.addEventListener('input',e=>{const f=e.target.closest('form[hx-get]');if(!f)return;clearTimeout(f._hx);f._hx=setTimeout(()=>request(f),250)});document.addEventListener('change',e=>{const f=e.target.closest('form[hx-get]');if(f)request(f)});})();
